ChatViewModel.swift

```swift
import Foundation
import Combine

@MainActor
class ChatViewModel: ObservableObject {
    @Published var messages: [Message] = []
    @Published var isSearching = false
    @Published var searchCount = 0

    private let cerebrasService = CerebrasService()
    private let exaService = ExaService()

    func sendMessage(_ text: String) async {
        let userMessage = Message(text: text, isUser: true)
        messages.append(userMessage)

        isSearching = true
        searchCount = 0

        var allSearchResults: [ExaSearchResult] = []
        var searchQueries: [String] = []

        let initialQuery = generateSearchQuery(from: text)
        searchQueries.append(initialQuery)

        while searchQueries.count > 0 && allSearchResults.count < 500 {
            let currentQuery = searchQueries.removeFirst()
            searchCount += 1

            let searchResults = await exaService.search(query: currentQuery, numResults: 100)
            allSearchResults.append(contentsOf: searchResults)

            if shouldContinueSearching(results: allSearchResults, originalQuery: text) {
                if let additionalQueries = await generateAdditionalQueries(from: text, existingResults: allSearchResults) {
                    searchQueries.append(contentsOf: additionalQueries)
                }
            } else {
                break
            }
        }

        isSearching = false

        let context = buildContext(from: allSearchResults)
        let aiResponse = await cerebrasService.generateResponse(userMessage: text, context: context, conversationHistory: messages)

        let assistantMessage = Message(text: aiResponse, isUser: false)
        messages.append(assistantMessage)
    }

    private func generateSearchQuery(from text: String) -> String {
        return text
    }

    private func shouldContinueSearching(results: [ExaSearchResult], originalQuery: String) -> Bool {
        if results.count >= 500 {
            return false
        }

        if results.count < 50 {
            return true
        }

        let relevantResults = results.filter { result in
            let titleMatch = result.title.lowercased().contains(originalQuery.lowercased())
            let textMatch = result.text?.lowercased().contains(originalQuery.lowercased()) ?? false
            return titleMatch || textMatch
        }

        return Double(relevantResults.count) / Double(results.count) > 0.3
    }

    private func generateAdditionalQueries(from originalQuery: String, existingResults: [ExaSearchResult]) async -> [String]? {
        let prompt = "A következő keresési eredmények alapján generálj 2-3 további keresési lekérdezést, amelyek segítenek mélyebben megérteni ezt a témát: \(originalQuery). Eredmények: \(existingResults.prefix(5).map { $0.title }.joined(separator: ", ")). Csak a keresési lekérdezéseket add meg, soronként egyet."

        let additionalQueries = await cerebrasService.generateSearchQueries(prompt: prompt)
        return additionalQueries
    }

    private func buildContext(from results: [ExaSearchResult]) -> String {
        var context = ""
        for result in results.prefix(100) {
            context += "Cím: \(result.title)\n"
            context += "URL: \(result.url)\n"
            if let text = result.text {
                context += "Szöveg: \(text.prefix(500))\n"
            }
            context += "\n"
        }
        return context
    }
}
