CerebrasService.swift

```swift
import Foundation

class CerebrasService {
    private let baseURL = ""
    private let model = "glm-4.6"

    private var apiKey: String {
        UserDefaults.standard.string(forKey: "cerebrasApiKey") ?? ""
    }

    func generateResponse(userMessage: String, context: String, conversationHistory: [Message]) async -> String {
        guard !apiKey.isEmpty else {
            return "Hiba: Cerebras API kulcs nincs beállítva. Kérlek add meg a beállításokban."
        }

        var messages: [[String: String]] = []

        messages.append([
            "role": "system",
            "content": "Te egy magyar nyelvű AI asszisztens vagy. Mindig magyarul válaszolj. A rendelkezésedre álló keresési eredmények alapján adj részletes és pontos válaszokat. Ha a keresési eredményekből idézel, hivatkozz a forrásra."
        ])

        if !context.isEmpty {
            messages.append([
                "role": "system",
                "content": "Keresési eredmények:\n\n\(context)"
            ])
        }

        for message in conversationHistory.suffix(10) {
            messages.append([
                "role": message.isUser ? "user" : "assistant",
                "content": message.text
            ])
        }

        messages.append([
            "role": "user",
            "content": userMessage
        ])

        let requestBody: [String: Any] = [
            "model": model,
            "messages": messages,
            "temperature": 0.7,
            "max_tokens": 4000,
            "stream": false
        ]

        guard let url = URL(string: "\(baseURL)/chat/completions") else {
            return "Hiba: Érvénytelen URL."
        }

        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        do {
            request.httpBody = try JSONSerialization.data(withJSONObject: requestBody)

            let (data, response) = try await URLSession.shared.data(for: request)

            guard let httpResponse = response as? HTTPURLResponse else {
                return "Hiba: Érvénytelen válasz."
            }

            if httpResponse.statusCode != 200 {
                if let errorJson = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                   let error = errorJson["error"] as? [String: Any],
                   let message = error["message"] as? String {
                    return "Hiba: \(message)"
                }
                return "Hiba: HTTP \(httpResponse.statusCode)"
            }

            if let json = try JSONSerialization.jsonObject(with: data) as? [String: Any],
               let choices = json["choices"] as? [[String: Any]],
               let firstChoice = choices.first,
               let message = firstChoice["message"] as? [String: Any],
               let content = message["content"] as? String {
                return content
            }

            return "Hiba: Nem sikerült feldolgozni a választ."
        } catch {
            return "Hiba: \(error.localizedDescription)"
        }
    }

    func generateSearchQueries(prompt: String) async -> [String]? {
        guard !apiKey.isEmpty else {
            return nil
        }

        let messages: [[String: String]] = [
            [
                "role": "system",
                "content": "Te egy keresési lekérdezés generátor vagy. Csak keresési lekérdezéseket generálj, soronként egyet, minden egyéb szöveg nélkül."
            ],
            [
                "role": "user",
                "content": prompt
            ]
        ]

        let requestBody: [String: Any] = [
            "model": model,
            "messages": messages,
            "temperature": 0.8,
            "max_tokens": 200,
            "stream": false
        ]

        guard let url = URL(string: "\(baseURL)/chat/completions") else {
            return nil
        }

        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        do {
            request.httpBody = try JSONSerialization.data(withJSONObject: requestBody)
            let (data, _) = try await URLSession.shared.data(for: request)

            if let json = try JSONSerialization.jsonObject(with: data) as? [String: Any],
               let choices = json["choices"] as? [[String: Any]],
               let firstChoice = choices.first,
               let message = firstChoice["message"] as? [String: Any],
               let content = message["content"] as? String {
                let queries = content.split(separator: "\n").map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty }
                return Array(queries.prefix(3))
            }

            return nil
        } catch {
            return nil
        }
    }
}
