ExaService.swift

```swift
import Foundation

struct ExaSearchResult: Codable, Identifiable {
    let id: String
    let title: String
    let url: String
    let text: String?
    let publishedDate: String?
    let author: String?
}

struct ExaSearchResponse: Codable {
    let requestId: String
    let results: [ExaSearchResult]
}

class ExaService {
    private let baseURL = ""

    private var apiKey: String {
        UserDefaults.standard.string(forKey: "exaApiKey") ?? ""
    }

    func search(query: String, numResults: Int = 100) async -> [ExaSearchResult] {
        guard !apiKey.isEmpty else {
            return []
        }

        let requestBody: [String: Any] = [
            "query": query,
            "type": "fast",
            "numResults": min(numResults, 100),
            "contents": [
                "text": true
            ]
        ]

        guard let url = URL(string: "\(baseURL)/search") else {
            return []
        }

        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue(apiKey, forHTTPHeaderField: "x-api-key")
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        do {
            request.httpBody = try JSONSerialization.data(withJSONObject: requestBody)
            let (data, response) = try await URLSession.shared.data(for: request)

            guard let httpResponse = response as? HTTPURLResponse, httpResponse.statusCode == 200 else {
                return []
            }

            let decoder = JSONDecoder()
            let searchResponse = try decoder.decode(ExaSearchResponse.self, from: data)
            return searchResponse.results
        } catch {
            return []
        }
    }
}
