import Foundation

final class CerebrasClient {
    private let baseURL: URL
    private let modelId: String
    private let urlSession: URLSession

    init(baseURL: URL = URL(string: "")!, modelId: String = "zai-glm-4.6", urlSession: URLSession = .shared) {
        self.baseURL = baseURL
        self.modelId = modelId
        self.urlSession = urlSession
    }

    func chat(messages: [CerebrasChatMessage], temperature: Double? = 0.4, maxTokens: Int? = 2200, responseFormat: CerebrasResponseFormat? = nil, apiKey: String) async throws -> CerebrasChatResponse {
        let endpoint = baseURL.appendingPathComponent("chat/completions")
        var request = URLRequest(url: endpoint)
        request.httpMethod = "POST"
        request.setValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        let body = CerebrasChatRequest(
            model: modelId,
            messages: messages,
            temperature: temperature,
            max_tokens: maxTokens,
            stream: false,
            response_format: responseFormat
        )

        let encoder = JSONEncoder()
        request.httpBody = try encoder.encode(body)

        let (data, response) = try await urlSession.data(for: request)
        guard let http = response as? HTTPURLResponse else {
            throw URLError(.badServerResponse)
        }

        guard (200...299).contains(http.statusCode) else {
            let text = String(data: data, encoding: .utf8) ?? ""
            throw NSError(domain: "CerebrasHTTPError", code: http.statusCode, userInfo: ["body": text])
        }

        let decoder = JSONDecoder()
        return try decoder.decode(CerebrasChatResponse.self, from: data)
    }
}
