import Foundation

final class ExaClient {
    private let baseURL: URL
    private let urlSession: URLSession

    init(baseURL: URL = URL(string: "")!, urlSession: URLSession = .shared) {
        self.baseURL = baseURL
        self.urlSession = urlSession
    }

    func search(requestBody: ExaSearchRequest, apiKey: String) async throws -> ExaSearchResponse {
        let endpoint = baseURL.appendingPathComponent("search")
        var request = URLRequest(url: endpoint)
        request.httpMethod = "POST"
        request.setValue(apiKey, forHTTPHeaderField: "x-api-key")
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        let encoder = JSONEncoder()
        request.httpBody = try encoder.encode(requestBody)

        let (data, response) = try await urlSession.data(for: request)
        guard let http = response as? HTTPURLResponse else {
            throw URLError(.badServerResponse)
        }

        guard (200...299).contains(http.statusCode) else {
            let text = String(data: data, encoding: .utf8) ?? ""
            throw NSError(domain: "ExaHTTPError", code: http.statusCode, userInfo: ["body": text])
        }

        let decoder = JSONDecoder()
        return try decoder.decode(ExaSearchResponse.self, from: data)
    }
}
