```swift
import Foundation

@MainActor
final class ChatViewModel: ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []
    @Published private(set) var isSearching: Bool = false
    @Published private(set) var searchCount: Int = 0
    @Published var isSettingsPresented: Bool = false
    @Published var lastErrorText: String?

    private let cerebras: CerebrasClient
    private let exa: ExaClient
    private let persistence: ChatPersistence

    private let maxSearchIterations: Int = 30
    private let maxUniqueResultsInContext: Int = 120
    private let maxCharsPerResult: Int = 2000

    init(cerebras: CerebrasClient = CerebrasClient(), exa: ExaClient = ExaClient(), persistence: ChatPersistence = ChatPersistence()) {
        self.cerebras = cerebras
        self.exa = exa
        self.persistence = persistence
        self.messages = persistence.load()
    }

    func clearChat() {
        messages.removeAll()
        persistence.save(messages)
    }

    func send(text: String) async {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }

        lastErrorText = nil
        messages.append(ChatMessage(role: .user, text: trimmed))
        persistence.save(messages)

        guard let cerebrasKey = AppSecrets.readCerebrasKey(), !cerebrasKey.isEmpty else {
            messages.append(ChatMessage(role: .assistant, text: "Hiányzik a Cerebras API kulcs. Nyisd meg a Beállításokat és add meg."))
            persistence.save(messages)
            return
        }

        guard let exaKey = AppSecrets.readExaKey(), !exaKey.isEmpty else {
            messages.append(ChatMessage(role: .assistant, text: "Hiányzik az Exa API kulcs. Nyisd meg a Beállításokat és add meg."))
            persistence.save(messages)
            return
        }

        isSearching = true
        searchCount = 0

        let userQuestion = trimmed
        var allResultsByURL: [String: ExaSearchResult] = [:]
        var pendingQueries: [String] = [userQuestion]

        for iteration in 0..<maxSearchIterations {
            if pendingQueries.isEmpty {
                break
            }

            let query = pendingQueries.removeFirst()
            searchCount += 1

            do {
                let req = ExaSearchRequest(query: query, type: "fast", numResults: 100, contents: ExaContentsRequest(text: true, highlights: false, summary: false), useModeration: true, context: false)
                let resp = try await exa.search(requestBody: req, apiKey: exaKey)

                for r in resp.results {
                    if allResultsByURL[r.url] == nil {
                        allResultsByURL[r.url] = r
                    }
                }
            } catch {
                lastErrorText = "Exa hiba: \(error.localizedDescription)"
                break
            }

            if iteration == maxSearchIterations - 1 {
                break
            }

            let plan = await proposeSearchPlan(question: userQuestion, results: Array(allResultsByURL.values), apiKey: cerebrasKey)
            if plan.continue {
                for q in plan.queries {
                    let t = q.trimmingCharacters(in: .whitespacesAndNewlines)
                    if !t.isEmpty && !pendingQueries.contains(t) {
                        pendingQueries.append(t)
                    }
                }
            } else {
                break
            }
        }

        isSearching = false

        let context = buildContext(results: Array(allResultsByURL.values))
        do {
            let reply = try await answer(question: userQuestion, context: context, apiKey: cerebrasKey)
            messages.append(ChatMessage(role: .assistant, text: reply))
            persistence.save(messages)
        } catch {
            lastErrorText = "Cerebras hiba: \(error.localizedDescription)"
            messages.append(ChatMessage(role: .assistant, text: "Hiba történt a válasz generálása közben. Ellenőrizd a kulcsokat és a hálózatot."))
            persistence.save(messages)
        }
    }

    private func proposeSearchPlan(question: String, results: [ExaSearchResult], apiKey: String) async -> SearchPlan {
        let compact = buildPlannerContext(results: results)
        let schema: JSONValue = .object([
            "type": .string("object"),
            "additionalProperties": .bool(false),
            "properties": .object([
                "continue": .object(["type": .string("boolean")]),
                "queries": .object([
                    "type": .string("array"),
                    "maxItems": .number(5),
                    "items": .object(["type": .string("string")])
                ]),
                "reason": .object(["type": .string("string")])
            ]),
            "required": .array([.string("continue"), .string("queries"), .string("reason")])
        ])

        let responseFormat = CerebrasResponseFormat(
            type: "json_schema",
            json_schema: CerebrasJSONSchema(name: "SearchPlan", strict: true, schema: schema)
        )

        let sys = """
Te egy kutatási tervező vagy. Feladat: dönts el, hogy kell-e még webes keresés a kérdés legjobb megválaszolásához.
Ha kell, adj 1-5 új, pontos keresési lekérdezést magyarul vagy angolul (amelyik jobb), és indokold röviden.
Csak a megadott JSON sémának megfelelő objektumot add vissza.
"""
        let user = """
Kérdés:
\(question)

Jelenlegi találatok (tömörítve):
\(compact)

Szabály:
Ha a találatok alapján már megadható egy jól alátámasztott, forrásokra hivatkozó válasz, akkor continue legyen false.
"""

        do {
            let resp = try await cerebras.chat(
                messages: [
                    CerebrasChatMessage(role: "system", content: sys),
                    CerebrasChatMessage(role: "user", content: user)
                ],
                temperature: 0.2,
                maxTokens: 500,
                responseFormat: responseFormat,
                apiKey: apiKey
            )

            guard let content = resp.choices.first?.message.content else {
                return SearchPlan(continue: false, queries: [], reason: "Üres válasz")
            }

            guard let data = content.data(using: .utf8) else {
                return SearchPlan(continue: false, queries: [], reason: "Nem UTF-8")
            }

            let decoder = JSONDecoder()
            if let plan = try? decoder.decode(SearchPlan.self, from: data) {
                let cleaned = plan.queries
                    .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                    .filter { !$0.isEmpty }
                return SearchPlan(continue: plan.continue, queries: cleaned, reason: plan.reason)
            }

            return SearchPlan(continue: false, queries: [], reason: "Nem dekódolható JSON")
        } catch {
            return SearchPlan(continue: false, queries: [], reason: "Tervező hiba")
        }
    }

    private func answer(question: String, context: String, apiKey: String) async throws -> String {
        let sys = """
Te egy magyar nyelvű asszisztens vagy. Mindig magyarul válaszolj.
A válasz legyen alátámasztva a megadott forráskivonatokkal, és a végén adj forráslistát URL-ekkel.
Ne találd ki a tényeket. Ha valami nem állapítható meg a forrásból, írd le egyértelműen.
"""
        let convo = makeConversationMessages(limit: 14)
        let user = """
Kérdés:
\(question)

Forráskivonatok:
\(context)
"""

        let resp = try await cerebras.chat(
            messages: [CerebrasChatMessage(role: "system", content: sys)] + convo + [CerebrasChatMessage(role: "user", content: user)],
            temperature: 0.4,
            maxTokens: 2200,
            responseFormat: nil,
            apiKey: apiKey
        )

        return resp.choices.first?.message.content ?? "Nem érkezett válasz."
    }

    private func makeConversationMessages(limit: Int) -> [CerebrasChatMessage] {
        let tail = messages.suffix(limit)
        return tail.map { m in
            CerebrasChatMessage(role: m.role == .user ? "user" : "assistant", content: m.text)
        }
    }

    private func buildPlannerContext(results: [ExaSearchResult]) -> String {
        let uniq = Array(results.prefix(40))
        var blocks: [String] = []
        blocks.reserveCapacity(uniq.count)

        for r in uniq {
            var b = ""
            b += "URL: \(r.url)\n"
            if let t = r.title, !t.isEmpty { b += "Cím: \(t)\n" }
            if let p = r.publishedDate, !p.isEmpty { b += "Dátum: \(p)\n" }
            if let a = r.author, !a.isEmpty { b += "Szerző: \(a)\n" }
            if let s = r.summary, !s.isEmpty { b += "Összefoglaló: \(truncate(s, max: 400))\n" }
            if let tx = r.text, !tx.isEmpty { b += "Szöveg: \(truncate(tx, max: 600))\n" }
            blocks.append(b)
        }

        return blocks.joined(separator: "\n---\n")
    }

    private func buildContext(results: [ExaSearchResult]) -> String {
        let sorted = results.sorted { ($0.score ?? 0) > ($1.score ?? 0) }
        let limited = Array(sorted.prefix(maxUniqueResultsInContext))

        var blocks: [String] = []
        blocks.reserveCapacity(limited.count)

        for r in limited {
            var b = ""
            b += "URL: \(r.url)\n"
            if let t = r.title, !t.isEmpty { b += "Cím: \(t)\n" }
            if let p = r.publishedDate, !p.isEmpty { b += "Dátum: \(p)\n" }
            if let a = r.author, !a.isEmpty { b += "Szerző: \(a)\n" }

            if let tx = r.text, !tx.isEmpty {
                b += "Kivonat: \(truncate(tx, max: maxCharsPerResult))\n"
            } else if let s = r.summary, !s.isEmpty {
                b += "Kivonat: \(truncate(s, max: maxCharsPerResult))\n"
            }

            blocks.append(b)
        }

        return blocks.joined(separator: "\n\n")
    }

    private func truncate(_ s: String, max: Int) -> String {
        if s.count <= max { return s }
        let idx = s.index(s.startIndex, offsetBy: max)
        return String(s[..<idx])
    }
}
